DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.registrar_cinta_v3(uuid,integer,numeric,numeric,text,text,text,uuid)'::regprocedure) INTO d; d:=replace(d,'IF v_sku IS NOT NULL AND NOT EXISTS','SELECT * INTO v_lote FROM public.pesajes_cintas_lotes WHERE id = _lote_id; IF v_lote.imp_bobina_id IS NOT NULL THEN v_sku := v_lote.datos_calidad_snapshot->>''sku''; END IF; IF v_lote.imp_bobina_id IS NULL AND v_sku IS NOT NULL AND NOT EXISTS'); EXECUTE d; SELECT pg_get_functiondef('public.preparar_impresion_etiquetas(uuid,text,uuid)'::regprocedure) INTO d; d:=replace(d,'SELECT id, posicion, uniones, peso_cinta_kg, ancho_util, ancho_util_unidad,','SELECT id, posicion, uniones, peso_cinta_kg, ancho_util, ancho_util_unidad, sku_sap, lote_logistico_pza, estatus_liberacion,'); d:=replace(d,'''muestra_calidad_id'', v_lote.muestra_calidad_id,','''imp_bobina_id'', v_lote.imp_bobina_id, ''muestra_calidad_id'', v_lote.muestra_calidad_id,'); d:=replace(d,'IF v_lote.id IS NULL THEN','IF v_lote.imp_bobina_id IS NOT NULL AND NOT public.user_sees_planta(v_uid,v_lote.planta_corte_id) THEN RAISE EXCEPTION ''Sin permiso de planta'' USING ERRCODE=''42501''; END IF; IF v_lote.id IS NULL THEN'); EXECUTE d; SELECT pg_get_functiondef('public.trazabilidad_lote_cintas(uuid)'::regprocedure) INTO d; d:=replace(d,'WHERE l.id = _lote_id AND l.estado <> ''anulado''','WHERE l.id = _lote_id AND l.estado <> ''anulado'' AND l.imp_bobina_id IS NULL'); EXECUTE d; SELECT pg_get_functiondef('public.pc_puede_editar_corte(uuid)'::regprocedure) INTO d; d:=replace(d,'COALESCE(mq1.codigo, mq2.codigo)','COALESCE(mq1.codigo, mq2.codigo, CASE WHEN l.imp_bobina_id IS NOT NULL THEN CASE WHEN (SELECT codigo FROM public.plantas WHERE id=l.planta_corte_id)=''IXT'' THEN ''MP-01'' ELSE ''MP-04'' END END)'); EXECUTE d; END $$;
COMMENT ON COLUMN public.pesajes_cintas_lotes.imp_bobina_id IS 'Explicit imported mother-roll source; no manufacturing order, sample or product linkage. Excluded from production reports and public trace.';